package com.ginga.naviai.knowledge.repository;

import com.ginga.naviai.knowledge.entity.Knowledge;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import org.springframework.stereotype.Repository;

import java.time.Instant;
import java.util.List;

@Repository
public interface KnowledgeRepository extends JpaRepository<Knowledge, Long> {

    long countByDeletedFalse();

    long countByCreatedAtAfterAndDeletedFalse(Instant start);

    long countByStatusAndDeletedFalse(String status);

    @Query(value = "SELECT t.name as tag, COUNT(kt.knowledge_id) as count " +
                   "FROM tag t " +
                   "JOIN knowledge_tag kt ON t.id = kt.tag_id " +
                   "GROUP BY t.name " +
                   "ORDER BY count DESC " +
                   "LIMIT :limit", nativeQuery = true)
    List<Object[]> findTopTags(@Param("limit") int limit);

    @Query("SELECT k FROM Knowledge k WHERE k.status = 'published' AND k.deleted = false ORDER BY k.publishedAt DESC")
    List<Knowledge> findRecentArticles(Pageable pageable);

    @Query(value = "SELECT k.id, k.title, u.display_name, k.published_at, COUNT(l.id) as like_count " +
                   "FROM knowledge k " +
                   "LEFT JOIN users u ON k.author_id = u.id " +
                   "LEFT JOIN \"like\" l ON k.id = l.knowledge_id " +
                   "WHERE k.status = 'published' AND k.is_deleted = false " +
                   "GROUP BY k.id, k.title, k.published_at, u.display_name " +
                   "ORDER BY like_count DESC, k.published_at DESC " +
                   "LIMIT :limit", nativeQuery = true)
    List<Object[]> findTopRecommendedArticles(@Param("limit") int limit);

    /**
     * 公開トップ画面の「今週の注目」向け。
     * 公開/非公開を問わず、未削除記事をいいね数の多い順で取得する。
     */
    @Query(value = "SELECT k.id, k.title, COUNT(l.id) as like_count " +
                   "FROM knowledge k " +
                   "LEFT JOIN \"like\" l ON k.id = l.knowledge_id " +
                   "WHERE k.is_deleted = false " +
                   "GROUP BY k.id, k.title " +
                   "ORDER BY like_count DESC, k.created_at DESC " +
                   "LIMIT :limit", nativeQuery = true)
    List<Object[]> findTopRecommendedArticlesAll(@Param("limit") int limit);

    long countByCreatedAtBetweenAndDeletedFalse(Instant start, Instant end);

    /**
     * 指定期間内に作成された記事の作成日時一覧を1回のクエリで取得する。
     * <p>
     * 週次アクティビティ集計で N+1 問題を回避するために使用する。
     * 期間を絞った上でアプリケーション側で週別に集計する。
     * </p>
     */
    @Query("SELECT k.createdAt FROM Knowledge k WHERE k.deleted = false AND k.createdAt >= :start AND k.createdAt < :end")
    List<Instant> findCreatedAtInRange(@Param("start") Instant start, @Param("end") Instant end);

    Page<Knowledge> findByAuthorId(Long authorId, Pageable pageable);

    Page<Knowledge> findByAuthorUsername(String username, Pageable pageable);

    /**
     * 公開記事（visibility=public かつ status=published かつ未削除）をページ取得する。
     * SCR-12 公開トップ画面向け。認証不要エンドポイントから呼ばれる。
     */
    @Query("SELECT k FROM Knowledge k WHERE k.visibility = 'public' AND k.status = 'published' AND k.deleted = false ORDER BY k.publishedAt DESC")
    Page<Knowledge> findPublicKnowledge(Pageable pageable);
}

package com.ginga.naviai.knowledge.service;

import com.ginga.naviai.knowledge.dto.PublicRecommendedKnowledgeResponse;
import com.ginga.naviai.knowledge.dto.PublicKnowledgePageResponse;
import org.springframework.data.domain.Pageable;

/**
 * 公開トップ画面（SCR-12）向けナレッジ取得サービス。
 * 認証不要エンドポイントからのみ利用する。
 */
public interface PublicKnowledgeService {

    /**
     * 公開記事一覧を取得する。
     * visibility=public かつ status=published かつ未削除の記事のみ返す。
     */
    PublicKnowledgePageResponse getPublicKnowledge(Pageable pageable);

    /**
     * 「今週の注目」向けのおすすめ記事を取得する。
     * 公開/非公開を問わず、未削除記事をいいね数降順で返す。
     */
    PublicRecommendedKnowledgeResponse getRecommendedKnowledge(int limit);
}

package com.ginga.naviai.knowledge.service;

import com.ginga.naviai.knowledge.dto.PublicKnowledgeItemDto;
import com.ginga.naviai.knowledge.dto.PublicKnowledgePageResponse;
import com.ginga.naviai.knowledge.dto.PublicRecommendedKnowledgeItemDto;
import com.ginga.naviai.knowledge.dto.PublicRecommendedKnowledgeResponse;
import com.ginga.naviai.knowledge.entity.Knowledge;
import com.ginga.naviai.knowledge.entity.Tag;
import com.ginga.naviai.knowledge.repository.KnowledgeRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;

@Service
@RequiredArgsConstructor
public class PublicKnowledgeServiceImpl implements PublicKnowledgeService {

    private final KnowledgeRepository knowledgeRepository;

    @Override
    @Transactional(readOnly = true)
    public PublicKnowledgePageResponse getPublicKnowledge(Pageable pageable) {
        Page<Knowledge> page = knowledgeRepository.findPublicKnowledge(pageable);

        List<PublicKnowledgeItemDto> items = page.getContent().stream()
                .map(this::toDto)
                .toList();

        return PublicKnowledgePageResponse.builder()
                .page(page.getNumber())
                .size(page.getSize())
                .totalElements(page.getTotalElements())
                .items(items)
                .build();
    }

    @Override
    @Transactional(readOnly = true)
    public PublicRecommendedKnowledgeResponse getRecommendedKnowledge(int limit) {
        int cappedLimit = Math.max(1, Math.min(limit, 10));
        List<Object[]> rows = knowledgeRepository.findTopRecommendedArticlesAll(cappedLimit);

        List<PublicRecommendedKnowledgeItemDto> items = rows.stream()
                .map(this::toRecommendedDto)
                .toList();

        return PublicRecommendedKnowledgeResponse.builder()
                .items(items)
                .build();
    }

    private PublicKnowledgeItemDto toDto(Knowledge k) {
        List<String> tagNames = k.getTags().stream()
                .map(Tag::getName)
                .sorted()
                .toList();

        String authorDisplayName = (k.getAuthor() != null && k.getAuthor().getDisplayName() != null)
                ? k.getAuthor().getDisplayName()
                : "";

        return PublicKnowledgeItemDto.builder()
                .id(k.getId())
                .title(k.getTitle())
                .excerpt(k.getExcerpt())
                .thumbnail(k.getThumbnail())
                .authorDisplayName(authorDisplayName)
                .publishedAt(k.getPublishedAt())
                .tags(tagNames)
                .build();
    }

        private PublicRecommendedKnowledgeItemDto toRecommendedDto(Object[] row) {
                Long id = ((Number) row[0]).longValue();
                String title = String.valueOf(row[1]);
                long likeCount = row[2] == null ? 0L : ((Number) row[2]).longValue();

                return PublicRecommendedKnowledgeItemDto.builder()
                                .id(id)
                                .title(title)
                                .likeCount(likeCount)
                                .build();
        }
}

package com.ginga.naviai.knowledge.controller;

import com.ginga.naviai.knowledge.dto.PublicKnowledgePageResponse;
import com.ginga.naviai.knowledge.dto.PublicRecommendedKnowledgeResponse;
import com.ginga.naviai.knowledge.service.PublicKnowledgeService;
import lombok.RequiredArgsConstructor;
import org.springframework.data.domain.PageRequest;
import org.springframework.data.domain.Pageable;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

/**
 * 公開トップ画面（SCR-12）向けナレッジ取得コントローラー。
 * 認証不要（SecurityConfig で /api/v1/public/** を permitAll に設定済み）。
 */
@RestController
@RequestMapping("/api/v1/public/knowledge")
@RequiredArgsConstructor
public class PublicKnowledgeController {

    private final PublicKnowledgeService publicKnowledgeService;

    /**
     * 公開記事一覧を取得する。
     *
     * @param page ページ番号（0始まり、デフォルト: 0）
     * @param size 1ページあたりの件数（デフォルト: 10）
     * @return 公開記事のページングレスポンス
     */
    @GetMapping
    public ResponseEntity<PublicKnowledgePageResponse> getPublicKnowledge(
            @RequestParam(defaultValue = "0") int page,
            @RequestParam(defaultValue = "10") int size) {

        Pageable pageable = PageRequest.of(page, Math.min(size, 50));
        return ResponseEntity.ok(publicKnowledgeService.getPublicKnowledge(pageable));
    }

    /**
     * 今週の注目（おすすめ）記事を取得する。
     * 公開/非公開を問わず、未削除記事をいいね数の多い順で返す。
     *
     * @param limit 取得件数（デフォルト: 1、最大: 10）
     */
    @GetMapping("/recommended")
    public ResponseEntity<PublicRecommendedKnowledgeResponse> getRecommendedKnowledge(
            @RequestParam(defaultValue = "1") int limit) {
        return ResponseEntity.ok(publicKnowledgeService.getRecommendedKnowledge(limit));
    }
}

'use client';
import React, { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import "./common_module.css";
import fetcher from "../lib/fetcher";

interface PublicArticle {
  id: number;
  title: string;
  excerpt: string | null;
  thumbnail: string | null;
  authorDisplayName: string;
  publishedAt: string | null;
  tags: string[];
}

interface PublicArticlesResponse {
  page: number;
  size: number;
  totalElements: number;
  items: PublicArticle[];
}

interface RecommendedArticle {
  id: number;
  title: string;
  likeCount: number;
}

interface RecommendedArticlesResponse {
  items: RecommendedArticle[];
}

interface TagItem {
  name: string;
  count: number;
}

export default function PublicHome() {
  const router = useRouter();
  const [articles, setArticles] = useState<PublicArticle[]>([]);
  const [recommended, setRecommended] = useState<RecommendedArticle | null>(null);
  const [tags, setTags] = useState<TagItem[]>([]);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    setIsAuthenticated(!!localStorage.getItem("token"));

    const fetchData = async () => {
      try {
        const [recommendedRes, articlesRes, tagsRes] = await Promise.all([
          fetcher<RecommendedArticlesResponse>("/api/v1/public/knowledge/recommended?limit=1", { skipAuth: true }),
          fetcher<PublicArticlesResponse>("/api/v1/public/knowledge?page=0&size=2", { skipAuth: true }),
          fetcher<TagItem[]>("/api/v1/public/tags", { skipAuth: true }),
        ]);
        setRecommended(recommendedRes.items?.[0] ?? null);
        setArticles(articlesRes.items ?? []);
        setTags(tagsRes);
      } catch (e) {
        setError("データの取得に失敗しました。");
        setRecommended(null);
        setArticles([]);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  const openKnowledge = (id: number) => {
    if (isAuthenticated) {
      router.push(`/knowledge/${id}`);
      return;
    }
    router.push(`/login?redirect=${encodeURIComponent(`/knowledge/${id}`)}`);
  };

  return (
    <div className="scr12-root">
      <header className="scr12-topbar container">
        <div className="brand">Ginga ナレッジ</div>
        <div className="search">キーワードで検索</div>
        <div className="auth">
          <button className="btn" onClick={() => router.push("/login")}>ログイン</button>
          <button
            className="btn"
            style={{ background: "var(--color-accent)", color: "#fff" }}
            onClick={() => router.push("/register")}
          >
            会員登録
          </button>
        </div>
      </header>

      <main className="scr12-main">
        <section>
          <div className="scr12-hero">
            {loading ? (
              <div className="title">読み込み中...</div>
            ) : recommended ? (
              <>
                <div className="title">今週の注目: {recommended.title}</div>
                <div className="desc">
                  いいね数 {recommended.likeCount} 件のおすすめ記事です。
                </div>
              </>
            ) : (
              <>
                <div className="title">データがありません</div>
                <div className="desc">おすすめ記事が登録されていません。</div>
              </>
            )}
            <div className="ctas">
              {recommended && (
                <button
                  className="btn"
                  style={{ background: "var(--color-accent)", color: "#fff" }}
                  onClick={() => openKnowledge(recommended.id)}
                >
                  {isAuthenticated ? "記事を読む" : "ログインして続きを読む"}
                </button>
              )}
              <button
                className="btn"
                style={{ background: "transparent", border: "1px solid var(--muted-ghost)" }}
                onClick={() => {
                  const el = document.querySelector(".scr12-article-list");
                  el?.scrollIntoView({ behavior: "smooth" });
                }}
              >
                公開記事を読む
              </button>
            </div>
          </div>

          {error && (
            <div style={{ color: "var(--color-danger)", marginTop: 16, padding: "8px 12px", background: "#fff0f0", borderRadius: 8 }}>
              {error}
            </div>
          )}

          <div className="scr12-article-list">
            {loading ? (
              [1, 2].map((i) => (
                <div key={i} className="scr12-article-row" style={{ opacity: 0.5 }}>
                  <div className="thumb" />
                  <div className="meta">
                    <div className="title" style={{ background: "#F3F6F9", height: 16, borderRadius: 4, width: "60%" }} />
                    <div className="excerpt" style={{ background: "#F3F6F9", height: 12, borderRadius: 4, width: "80%", marginTop: 8 }} />
                  </div>
                </div>
              ))
            ) : articles.length > 0 ? (
              articles.map((article) => (
                <div
                  key={article.id}
                  className="scr12-article-row"
                  style={{ cursor: "pointer" }}
                  onClick={() => openKnowledge(article.id)}
                  role="button"
                  tabIndex={0}
                  onKeyDown={(e) => { if (e.key === "Enter") openKnowledge(article.id); }}
                >
                  <div
                    className="thumb"
                    style={article.thumbnail ? { backgroundImage: `url(${article.thumbnail})`, backgroundSize: "cover" } : {}}
                  />
                  <div className="meta">
                    <div className="title">{article.title}</div>
                    <div className="excerpt">
                      {article.excerpt ?? ""}
                      {article.tags.length > 0 && (
                        <span style={{ marginLeft: 8, color: "var(--color-primary)", fontSize: 12 }}>
                          {article.tags.map((t) => `#${t}`).join(" ")}
                        </span>
                      )}
                    </div>
                    <div style={{ fontSize: 12, color: "var(--color-muted)", marginTop: 4 }}>
                      {article.authorDisplayName && <span>{article.authorDisplayName} · </span>}
                      {article.publishedAt && <span>{new Date(article.publishedAt).toLocaleDateString("ja-JP")}</span>}
                    </div>
                  </div>
                  <div className="badge">公開</div>
                </div>
              ))
            ) : !loading && !error && (
              <div style={{ color: "var(--color-muted)", padding: "16px 0" }}>データがありません</div>
            )}
          </div>
        </section>

        <aside className="scr12-side">
          <div className="widget">
            <div className="title">人気タグ</div>
            <div style={{ display: "flex", flexWrap: "wrap", gap: 8, marginTop: 8 }}>
              {loading ? (
                ["", "", ""].map((_, i) => (
                  <div
                    key={i}
                    style={{ padding: "6px 24px", borderRadius: 14, background: "#F3F6F9", color: "transparent" }}
                  >
                    &nbsp;
                  </div>
                ))
              ) : tags.length > 0 ? (
                tags.slice(0, 10).map((tag) => (
                  <div
                    key={tag.name}
                    style={{ padding: "6px 12px", borderRadius: 14, background: "#EAF2FF", color: "var(--color-primary)", fontSize: 13 }}
                  >
                    {tag.name}
                    {tag.count && (
                      <span style={{ marginLeft: 4, fontSize: 11, color: "var(--color-muted)" }}>({tag.count})</span>
                    )}
                  </div>
                ))
              ) : (
                <div style={{ color: "var(--color-muted)", fontSize: 13 }}>タグはまだありません。</div>
              )}
            </div>
          </div>

          <div className="scr12-footer-note">未ログイン: 一部コンテンツは制限されます</div>
        </aside>
      </main>
    </div>
  );
}

